"""Protocol-7 Module: Threshold Monitor

This module reads a threshold value from configuration with a default of 30,
and logs a warning if any monitored value exceeds the threshold.
"""

from typing import Any, Dict, Optional, Union
import logging
import os
import json


class ConfigError(Exception):
    """Custom exception for configuration errors."""
    pass


class Logger:
    """Protocol-7 logging module."""

    def __init__(self, name: str = "protocol7"):
        self.logger = logging.getLogger(name)
        self.logger.setLevel(logging.WARNING)
        handler = logging.StreamHandler()
        handler.setFormatter(logging.Formatter(
            "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
        ))
        self.logger.addHandler(handler)

    def warn(self, message: str, *args, **kwargs) -> None:
        """Log a warning message."""
        self.logger.warning(message, *args, **kwargs)

    def error(self, message: str, *args, **kwargs) -> None:
        """Log an error message."""
        self.logger.error(message, *args, **kwargs)


class Config:
    """Protocol-7 configuration module."""

    DEFAULTS: Dict[str, Any] = {
        "threshold": 30,
        "monitoring_interval": 60,
        "log_level": "WARNING",
    }

    def __init__(self, config_path: str = "config.json"):
        self.config_path = config_path
        self.config: Dict[str, Any] = {}
        self._load()

    def _load(self) -> None:
        """Load configuration from file or use defaults."""
        if not os.path.exists(self.config_path):
            self._use_defaults()
            return

        try:
            with open(self.config_path, "r") as f:
                self.config = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            raise ConfigError(f"Failed to load config: {e}")

    def _use_defaults(self) -> None:
        """Use default configuration values."""
        self.config = dict(self.DEFAULTS)

    def get(self, key: str, default: Any = None) -> Any:
        """Get a config value with optional default."""
        if key in self.config:
            return self.config[key]
        return default

    def set(self, key: str, value: Any) -> None:
        """Set a config value."""
        self.config[key] = value

    def save(self, path: Optional[str] = None) -> None:
        """Save configuration to file."""
